from pathlib import Path
import subprocess


def replace_once(path: Path, old: str, new: str, label: str) -> None:
    text = path.read_text()
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label} anchor changed: {count}")
    path.write_text(text.replace(old, new, 1))


compat = Path("src/4_semantics/global/call_compatibility.zig")
replace_once(
    compat,
    '''    pub fn compatible(self: @This(), actual: global_sg.GlobalTypeId, expected: global_sg.GlobalTypeId) bool {\n        const actual_pointer = switch (self.core.graph.types.items[@intFromEnum(actual)]) {\n            .pointer => |pointer| pointer,\n            else => return false,\n        };\n        const expected_pointer = switch (self.core.graph.types.items[@intFromEnum(expected)]) {\n            .pointer => |pointer| pointer,\n            else => return false,\n        };\n        if (expected_pointer.mutability == .read_write and actual_pointer.mutability != .read_write) return false;\n        return self.abstracts.concreteImplements(actual_pointer.child, expected_pointer.child);\n    }\n''',
    '''    pub fn compatible(self: @This(), actual: global_sg.GlobalTypeId, expected: global_sg.GlobalTypeId) bool {\n        const actual_pointer = switch (self.core.graph.types.items[@intFromEnum(actual)]) {\n            .pointer => |pointer| pointer,\n            else => return false,\n        };\n        const expected_pointer = switch (self.core.graph.types.items[@intFromEnum(expected)]) {\n            .pointer => |pointer| pointer,\n            else => return false,\n        };\n        if (expected_pointer.mutability == .read_write and actual_pointer.mutability != .read_write) return false;\n        const result = self.abstracts.concreteImplements(actual_pointer.child, expected_pointer.child);\n        std.debug.print(\n            "[abstract-compat] actual-child={}({s}) expected-child={}({s}) result={}\\n",\n            .{\n                @intFromEnum(actual_pointer.child),\n                @tagName(self.core.graph.types.items[@intFromEnum(actual_pointer.child)]),\n                @intFromEnum(expected_pointer.child),\n                @tagName(self.core.graph.types.items[@intFromEnum(expected_pointer.child)]),\n                result,\n            },\n        );\n        return result;\n    }\n''',
    "trace abstract call compatibility",
)

abstracts = Path("src/4_semantics/global/abstracts.zig")
replace_once(
    abstracts,
    '''    pub fn implements(\n        self: *Resolver,\n        concrete: global_sg.GlobalTypeId,\n        abstract_decl: global_sg.GlobalDeclId,\n    ) !bool {\n        self.stats.checks += 1;\n        for (self.modules, 0..) |*module, module_index| {\n            for (module.semantic.parameterized_storage.abstract_implementations.items) |implementation| {\n                const candidate_abstract = try self.resolveDeclarationRef(module_index, implementation.abstract_ref, .abstract_type);\n                if (candidate_abstract != abstract_decl) continue;\n                const candidate_type = globalizer.globalType(self.offsets[module_index], implementation.ty);\n                if (global_types.equal(self.graph, concrete, candidate_type)) {\n                    self.stats.concrete_hits += 1;\n                    return true;\n                }\n            }\n''',
    '''    pub fn implements(\n        self: *Resolver,\n        concrete: global_sg.GlobalTypeId,\n        abstract_decl: global_sg.GlobalDeclId,\n    ) !bool {\n        self.stats.checks += 1;\n        const wanted_abstract_name = self.graph.text(self.graph.declarations.items[@intFromEnum(abstract_decl)].name);\n        const concrete_name: []const u8 = switch (self.graph.types.items[@intFromEnum(concrete)]) {\n            .declared => |decl| self.graph.text(self.graph.declarations.items[@intFromEnum(decl)].name),\n            .generic => |generic| self.graph.text(self.graph.declarations.items[@intFromEnum(generic.base)].name),\n            else => "<non-nominal>",\n        };\n        for (self.modules, 0..) |*module, module_index| {\n            for (module.semantic.parameterized_storage.abstract_implementations.items) |implementation| {\n                const candidate_abstract = try self.resolveDeclarationRef(module_index, implementation.abstract_ref, .abstract_type);\n                const candidate_type = globalizer.globalType(self.offsets[module_index], implementation.ty);\n                const candidate_abstract_name = self.graph.text(self.graph.declarations.items[@intFromEnum(candidate_abstract)].name);\n                const candidate_type_name: []const u8 = switch (self.graph.types.items[@intFromEnum(candidate_type)]) {\n                    .declared => |decl| self.graph.text(self.graph.declarations.items[@intFromEnum(decl)].name),\n                    .generic => |generic| self.graph.text(self.graph.declarations.items[@intFromEnum(generic.base)].name),\n                    else => "<non-nominal>",\n                };\n                if (std.mem.eql(u8, candidate_abstract_name, wanted_abstract_name) or std.mem.eql(u8, candidate_type_name, concrete_name)) {\n                    std.debug.print(\n                        "[implements] concrete={}({s}:{s}) abstract={}({s}) candidate-abstract={}({s}) candidate-type={}({s}:{s}) same-abstract={} equal={}\\n",\n                        .{\n                            @intFromEnum(concrete),\n                            @tagName(self.graph.types.items[@intFromEnum(concrete)]),\n                            concrete_name,\n                            @intFromEnum(abstract_decl),\n                            wanted_abstract_name,\n                            @intFromEnum(candidate_abstract),\n                            candidate_abstract_name,\n                            @intFromEnum(candidate_type),\n                            @tagName(self.graph.types.items[@intFromEnum(candidate_type)]),\n                            candidate_type_name,\n                            candidate_abstract == abstract_decl,\n                            global_types.equal(self.graph, concrete, candidate_type),\n                        },\n                    );\n                }\n                if (candidate_abstract != abstract_decl) continue;\n                if (global_types.equal(self.graph, concrete, candidate_type)) {\n                    self.stats.concrete_hits += 1;\n                    return true;\n                }\n            }\n''',
    "trace concrete abstract implementation lookup",
)
subprocess.run(["zig", "fmt", str(compat), str(abstracts)], check=True)
Path(".git/semantic-refactor-message").write_text("Trace abstract implementation identity")
Path(".git/semantic-refactor-test-command").write_text(
    "zig build test-programs -Dtest-filter=feature_tests/collections/26_dynamic_array_owning_pop\n"
)
